export interface Article01Section {
  id: string;
  title: string;
  paragraphs: readonly string[];
  quote?: { text: string; attribution?: string };
  list?: readonly string[];
}
export interface Article01Image {
  src?: string;
  alt: string;
  caption?: string;
  credit?: string;
}
export interface Article01Graphic {
  label: string;
  title: string;
  index: string;
  caption?: string;
}
export interface Article01Link {
  id: string;
  title: string;
  detail: string;
  href?: string;
}
export interface Article01Author {
  name: string;
  role: string;
  bio: string;
  href?: string;
}
export interface Article01Props {
  publication?: string;
  issue?: string;
  category?: string;
  title?: string;
  standfirst?: string;
  dateTime?: string;
  dateLabel?: string;
  readingTime?: string;
  author?: Article01Author | null;
  cover?: Article01Image | null;
  graphic?: Article01Graphic | null;
  sections?: readonly Article01Section[];
  sources?: readonly Article01Link[];
  related?: readonly Article01Link[];
  backHref?: string;
  backLabel?: string;
  notice?: string;
}
export const sampleAuthor: Article01Author = {
  name: "Alex Morgan",
  role: "Designer & writer",
  bio: "Working at the intersection of useful systems and everyday life. Sample author details; replace with your own.",
};
export const sampleGraphic: Article01Graphic = {
  label: "FIELD NOTES / OBSERVATION NO. 01",
  title: "Good ideas need\nroom to grow.",
  index: "01",
  caption:
    "An exercise in paying attention. Typography and colour follow the active preset.",
};
export const sampleSections: readonly Article01Section[] = [
  {
    id: "attention",
    title: "Start with what is already there.",
    paragraphs: [
      "A useful idea often begins with a small observation. A question someone asks twice. A task that takes longer than it should. A quiet workaround that has become part of the day.",
      "Before adding another feature, spend a little time with the people who will use it. Notice what they keep close, what they skip, and where they hesitate. Those details give the work somewhere honest to begin.",
    ],
    list: [
      "Look at the whole task, not just the screen.",
      "Ask what people do when the expected path breaks.",
      "Keep the observation separate from the solution.",
    ],
  },
  {
    id: "connections",
    title: "The space between the parts.",
    paragraphs: [
      "A product is experienced as a whole. The vocabulary, the rhythm, and the way one decision leads to the next matter as much as any single element.",
      "Shared foundations make that continuity easier to maintain. They leave room for a distinct layout while keeping the small decisions familiar. A strong system is useful precisely because it does not have to make every page look the same.",
    ],
    quote: {
      text: "Consistency gives the details a common language. It should still leave the work something to say.",
      attribution: "From the studio notebook",
    },
  },
  {
    id: "restraint",
    title: "Make fewer decisions, more deliberately.",
    paragraphs: [
      "Every visible element asks for a little attention. Give the important ones room, let related things sit together, and choose a clear order for the story.",
      "Restraint is a practical editing process. Remove what repeats an idea without improving it. Keep the context that lets a person make a confident next move.",
    ],
  },
  {
    id: "practice",
    title: "Leave room for the next version.",
    paragraphs: [
      "The first useful version is a starting point. Put it in front of someone, observe it in use, and keep a record of what you learn.",
      "Good work can be both considered and unfinished. A clear structure makes the next change easier to see, and gives the next person a place to contribute.",
    ],
  },
];
export const sampleSources: readonly Article01Link[] = [
  {
    id: "note",
    title: "About this piece",
    detail:
      "An original sample essay for the Paraxe publication layout. Replace with your own reporting and sources.",
  },
];
export const sampleRelated: readonly Article01Link[] = [
  {
    id: "rhythm",
    title: "A rhythm you can return to.",
    detail: "Practice / 5 min read",
  },
  {
    id: "language",
    title: "A shared language, a different point of view.",
    detail: "Systems / 8 min read",
  },
  {
    id: "small",
    title: "The smallest useful thing.",
    detail: "Field notes / 4 min read",
  },
];
export function validateArticle(
  sections: readonly Article01Section[],
  sources: readonly Article01Link[] = [],
  related: readonly Article01Link[] = [],
) {
  for (const items of [sections, sources, related]) {
    const ids = new Set<string>();
    for (const item of items) {
      if (!/^[a-zA-Z0-9][a-zA-Z0-9_-]*$/.test(item.id) || ids.has(item.id))
        throw new RangeError("Article items require unique anchor-safe IDs.");
      ids.add(item.id);
    }
  }
}

.article01 {
  --article01-reading-width: var(--content-width-narrow);
  --article01-toc-width: calc(var(--space-4) * 13);
  --article01-reading-gap: calc(var(--space-4) * 5);
  padding: var(--space-6) var(--container-padding-lg) var(--space-10);
  background: var(--background-primary);
  color: var(--text-primary);
  font-family: var(--font-family-body);
}
.article01 *,
.article01 *::before,
.article01 *::after {
  box-sizing: border-box;
}
.article01-inner {
  max-width: var(--container-max-width);
  margin-inline: auto;
}
.article01 :is(h1, h2, h3, p, figure, blockquote, ol, ul) {
  margin: 0;
}
.article01 a {
  color: inherit;
  text-underline-offset: var(--space-1);
}
.article01 a:focus-visible {
  outline: var(--focus-ring-width) solid var(--focus-ring-color);
  outline-offset: var(--focus-ring-offset);
}
.article01 :is(section, article) {
  scroll-margin-block-start: var(--space-8);
}
.article01 .article01-masthead {
  padding-block-end: var(--space-5);
  border-block-end: var(--border-width-thin) solid var(--border-strong);
  gap: var(--space-4);
}
.article01-masthead > a {
  font-size: var(--font-size-xl);
  font-weight: var(--font-weight-bold);
  letter-spacing: var(--letter-spacing-tight);
  text-decoration: none;
}
.article01-masthead > a > span {
  color: var(--brand-primary);
}
.article01-masthead > span {
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
}
.article01-header {
  padding-block: var(--space-9) var(--space-8);
}
.article01-back {
  display: inline-block;
  margin-block-end: var(--space-6);
  font-size: var(--typography-caption-size);
}
.article01 .article01-overline {
  gap: var(--space-3);
  margin-block-end: var(--space-6);
  font-size: var(--typography-caption-size);
}
.article01-header h1 {
  max-width: var(--content-width-readable);
  font-size: var(--typography-hero-size);
  line-height: var(--line-height-tight);
  letter-spacing: var(--letter-spacing-tighter);
  text-wrap: balance;
}
.article01 .article01-deck {
  margin-block-start: var(--space-7);
  gap: var(--space-8);
}
.article01 .article01-standfirst {
  flex: 1 1 65%;
  max-width: var(--content-width-narrow);
  font-size: var(--typography-lead-size);
  line-height: var(--typography-lead-lineheight);
  color: var(--text-secondary);
}
.article01-byline {
  flex: 0 1 28%;
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
}
.article01-byline time {
  display: block;
  color: var(--text-muted);
  margin-block-start: var(--space-1);
}
.article01-cover {
  margin-block-end: var(--space-10);
}
.article01-cover .media {
  border-radius: var(--media-radius);
}
.article01 .article01-graphic {
  background: var(--brand-primary-muted);
  border-radius: var(--media-radius);
  padding: var(--space-7);
  gap: var(--space-8);
  overflow: hidden;
  border: var(--border-width-thin) solid var(--border-default);
}
.article01-graphic > div {
  flex: 1 1 65%;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: var(--space-8);
}
.article01-graphic p {
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wider);
}
.article01-graphic strong {
  white-space: pre-line;
  font-size: var(--typography-product-title-size);
  line-height: var(--line-height-tight);
  letter-spacing: var(--letter-spacing-tighter);
  font-weight: var(--typography-heading-weight);
}
.article01-graphic-index {
  flex: 0 1 30%;
  min-width: 0;
  font-size: calc(var(--font-size-8xl) * 2);
  line-height: var(--line-height-none);
  letter-spacing: var(--letter-spacing-tighter);
  color: var(--brand-primary);
  align-self: end;
}
.article01-cover figcaption {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-3);
  padding-block-start: var(--space-3);
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
  color: var(--text-muted);
}
.article01 .article01-reading {
  gap: var(--article01-reading-gap);
  max-width: calc(
    var(--article01-reading-width) + var(--article01-toc-width) +
      var(--article01-reading-gap)
  );
  margin-inline: auto;
}
.article01-toc {
  flex: 0 0 var(--article01-toc-width);
  min-width: 0;
  position: sticky;
  top: var(--space-7);
  padding-block-start: var(--space-1);
}
.article01 .article01-kicker {
  font-size: var(--typography-micro-size);
  line-height: var(--line-height-relaxed);
  letter-spacing: var(--letter-spacing-wider);
  font-weight: var(--font-weight-semibold);
  color: var(--text-muted);
}
.article01-toc ol {
  list-style: none;
  padding: 0;
  margin-block-start: var(--space-5);
  border-block-start: var(--border-width-thin) solid var(--border-default);
}
.article01-toc a {
  display: flex;
  gap: var(--space-3);
  padding-block: var(--space-4);
  border-block-end: var(--border-width-thin) solid var(--border-default);
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
  text-decoration: none;
}
.article01-toc a:hover {
  color: var(--text-accent);
}
.article01-toc a > span {
  font-size: var(--typography-micro-size);
  font-variant-numeric: tabular-nums;
  color: var(--text-muted);
}
.article01-side-note {
  margin-block-start: var(--space-8);
  padding-inline-start: var(--space-4);
  border-inline-start: var(--border-width-thin) solid var(--brand-primary);
  font-size: var(--typography-caption-size);
  color: var(--text-muted);
  line-height: var(--line-height-relaxed);
}
.article01-side-note > span {
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
}
.article01-side-note > p {
  margin-block-start: var(--space-3);
}
.article01-body {
  flex: 1 1 0;
  min-width: 0;
  max-width: var(--article01-reading-width);
}
.article01-section + .article01-section {
  margin-block-start: var(--space-10);
}
.article01-section h2 {
  margin-block: var(--space-3) var(--space-6);
  font-size: var(--font-size-3xl);
  letter-spacing: var(--typography-heading-letterspacing);
  line-height: var(--typography-heading-lineheight);
  text-wrap: balance;
}
.article01-section > p:not(.article01-kicker),
.article01-section > ul {
  font-size: var(--typography-body-large-size);
  line-height: var(--typography-body-large-lineheight);
}
.article01-section > p + p {
  margin-block-start: var(--space-5);
}
.article01-section ul {
  padding-inline-start: var(--space-6);
  margin-block-start: var(--space-6);
}
.article01-section li + li {
  margin-block-start: var(--space-3);
}
.article01-quote {
  margin-block: var(--space-9);
  padding: var(--space-6) 0 var(--space-6) var(--space-6);
  border-inline-start: var(--border-width-thin) solid var(--brand-primary);
}
.article01-quote blockquote {
  font-size: var(--font-size-2xl);
  line-height: var(--line-height-snug);
  letter-spacing: var(--letter-spacing-tight);
  font-weight: var(--font-weight-medium);
}
.article01-quote figcaption {
  margin-block-start: var(--space-4);
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
  color: var(--text-muted);
}
.article01-sources {
  margin-block-start: var(--space-10);
  padding-block-start: var(--space-6);
  border-block-start: var(--border-width-thin) solid var(--border-strong);
}
.article01-sources h2 {
  font-size: var(--font-size-xl);
  margin-block: var(--space-2) var(--space-5);
}
.article01-sources ol {
  list-style: none;
  padding: 0;
}
.article01-sources li {
  display: flex;
  gap: var(--space-4);
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
}
.article01-sources li + li {
  margin-block-start: var(--space-4);
}
.article01-sources li > span {
  color: var(--text-muted);
}
.article01-sources li p {
  margin-block-start: var(--space-2);
}
.article01-author {
  margin-block-start: var(--space-9);
  padding: var(--space-6);
  background: var(--surface-base);
  border-radius: var(--card-radius);
}
.article01-author h2 {
  font-size: var(--font-size-lg);
  margin-block: var(--space-2) var(--space-1);
}
.article01-author-role {
  font-size: var(--typography-caption-size);
  margin-block-end: var(--space-3);
}
.article01-author .text-muted {
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
}
.article01-avatar {
  flex: 0 0 var(--space-10);
  aspect-ratio: 1;
  display: grid;
  place-items: center;
  background: var(--background-primary);
  border-radius: var(--radius-full);
  font-size: var(--typography-caption-size);
}
.article01-related {
  margin-block-start: var(--space-12);
  padding-block-start: var(--space-7);
  border-block-start: var(--border-width-thin) solid var(--border-strong);
}
.article01-related > .flex {
  gap: var(--space-4);
}
.article01-related h2 {
  font-size: var(--font-size-3xl);
  letter-spacing: var(--letter-spacing-tight);
  margin-block-start: var(--space-2);
}
.article01-related > .flex > a {
  font-size: var(--typography-caption-size);
}
.article01 .article01-related-list {
  gap: var(--space-6);
  margin-block-start: var(--space-6);
}
.article01-related-list > div {
  flex: 1 1 28%;
  min-width: 0;
  padding-block-start: var(--space-4);
  border-block-start: var(--border-width-thin) solid var(--border-default);
}
.article01-related-index {
  display: block;
  font-size: var(--font-size-2xl);
  color: var(--text-muted);
  margin-block-end: var(--space-5);
}
.article01-related h3 {
  font-size: var(--font-size-xl);
  line-height: var(--line-height-snug);
  letter-spacing: var(--letter-spacing-tight);
  margin-block-end: var(--space-3);
}
.article01-related h3 a {
  text-decoration: none;
}
.article01-related h3 a:hover {
  text-decoration: underline;
}
.article01-related-list p {
  font-size: var(--typography-caption-size);
}
.article01-notice {
  margin-block-start: var(--space-8);
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
  color: var(--text-muted);
}
.article01-empty {
  padding-block: var(--space-8);
}
.article01-empty h2 {
  margin-block-end: var(--space-4);
}
.article01 :is(h1, h2, h3, p, a, strong) {
  overflow-wrap: anywhere;
}
@media (max-width: 900px) {
  .article01 {
    --article01-toc-width: calc(var(--space-4) * 10);
    --article01-reading-gap: var(--space-7);
    padding-inline: var(--container-padding);
  }
  .article01-graphic-index {
    font-size: var(--font-size-8xl);
  }
}
@media (max-width: 650px) {
  .article01 {
    padding-inline: var(--space-4);
  }
  .article01 .article01-reading {
    flex-direction: column;
  }
  .article01-toc {
    position: static;
    flex-basis: auto;
    width: 100%;
  }
  .article01-toc ol {
    display: flex;
    flex-wrap: wrap;
    gap: 0 var(--space-4);
  }
  .article01-toc li {
    flex: 1 1 40%;
  }
  .article01-side-note {
    display: none;
  }
  .article01 .article01-deck {
    flex-direction: column;
    align-items: start;
    gap: var(--space-5);
  }
  .article01 .article01-standfirst,
  .article01-byline {
    flex-basis: auto;
  }
  .article01 .article01-graphic {
    padding: var(--space-5);
  }
  .article01-graphic-index {
    display: none;
  }
  .article01-related-list > div {
    flex-basis: 100%;
  }
  .article01 .article01-header {
    padding-block: var(--space-7);
  }
}
